#!/bin/bash
set -euo pipefail
/data1/home/sunyiq/miniconda3/envs/nh_final/bin/python -I -B - <<'ZJ_TARGET_DEPLOY'
"""Template for a single, exclusive and source-verified cluster deployment.

The package builder replaces the two base64 placeholders before publication.
No scheduler job is submitted by this deployment command.
"""
from __future__ import annotations

import base64
from io import BytesIO
import hashlib
import json
import os
from pathlib import Path, PurePosixPath
import stat
import tarfile


PAYLOAD_BASE64 = ""
RECEIPT_BASE64 = ""
REMOTE = "/data1/home/sunyiq/zhenjiang_target_state_diagnostic_20260930_001"


def sha(raw):
    return hashlib.sha256(raw).hexdigest()


def canonical(value):
    return json.dumps(value, sort_keys=True, ensure_ascii=False,
                      separators=(",", ":"), allow_nan=False).encode()


def write_new(path, raw):
    path.parent.mkdir(parents=True, exist_ok=True, mode=0o700)
    flags = os.O_WRONLY | os.O_CREAT | os.O_EXCL | getattr(os, "O_NOFOLLOW", 0)
    fd = os.open(path, flags, 0o600)
    with os.fdopen(fd, "wb") as stream:
        stream.write(raw)
        stream.flush()
        os.fsync(stream.fileno())


def copy_registered_input(source, destination, specification):
    if (str(source) != specification["path"] or not str(source).startswith("/data1/home/sunyiq/")
            or source.is_symlink() or not source.is_file()
            or source.stat().st_size != specification["size_bytes"]):
        raise ValueError("registered training input path or size differs")
    destination.parent.mkdir(parents=True, exist_ok=True, mode=0o700)
    flags = os.O_WRONLY | os.O_CREAT | os.O_EXCL | getattr(os, "O_NOFOLLOW", 0)
    handle = os.open(destination, flags, 0o600)
    digest = hashlib.sha256()
    count = 0
    with source.open("rb") as left, os.fdopen(handle, "wb") as right:
        for block in iter(lambda: left.read(1 << 20), b""):
            right.write(block)
            digest.update(block)
            count += len(block)
        right.flush()
        os.fsync(right.fileno())
    if count != specification["size_bytes"] or digest.hexdigest() != specification["sha256"]:
        raise ValueError("registered training input content differs")


def main():
    os.umask(0o077)
    receipt = json.loads(base64.b64decode(RECEIPT_BASE64, validate=True))
    package = base64.b64decode(PAYLOAD_BASE64, validate=True)
    if (receipt["remote_root"] != REMOTE
            or len(package) != receipt["payload_bytes"]
            or sha(package) != receipt["payload_sha256"]
            or len(package) > 1_000_000):
        raise ValueError("deployment package identity differs")
    root = Path(REMOTE)
    if root.parent.resolve(strict=True) != root.parent or os.path.lexists(root):
        raise ValueError("exclusive cluster root is occupied")
    members = {}
    with tarfile.open(fileobj=BytesIO(package), mode="r:gz") as archive:
        for item in archive.getmembers():
            relative = PurePosixPath(item.name)
            if (not item.isfile() or relative.is_absolute() or ".." in relative.parts
                    or "\\" in item.name or item.name in members
                    or item.size > 2_000_000):
                raise ValueError("unsafe deployment archive member")
            entry = archive.extractfile(item)
            if entry is None:
                raise ValueError("missing archive member")
            raw = entry.read(item.size + 1)
            if len(raw) != item.size:
                raise ValueError("archive member size differs")
            members[item.name] = raw
    index_raw = members.get("deploy/payload_index.json")
    if index_raw is None or sha(index_raw) != receipt["payload_index_sha256"]:
        raise ValueError("archive index differs")
    index = json.loads(index_raw)
    if set(index) != set(members) - {"deploy/payload_index.json"}:
        raise ValueError("archive index member set differs")
    for name, expected in index.items():
        if len(members[name]) != expected["bytes"] or sha(members[name]) != expected["sha256"]:
            raise ValueError("archive member identity differs")
    protocol = json.loads(members["protocol.json"])
    registry = json.loads(members["registry_frozen.json"])
    manifest = json.loads(members["reports/training_manifest.json"])
    if (protocol["experiment_id"] != receipt["experiment_id"]
            or registry["experiment_id"] != receipt["experiment_id"]
            or manifest["experiment_id"] != receipt["experiment_id"]
            or registry["remote_root"] != REMOTE
            or registry["mandatory_runs"] != 24
            or registry["execution_ready"] is not True
            or len(protocol["training_inputs"]) != 10
            or sha(members["protocol.json"]) != receipt["protocol_sha256"]
            or sha(members["registry_frozen.json"]) != receipt["registry_sha256"]
            or sha(members["reports/training_manifest.json"]) != receipt["manifest_sha256"]
            or sha(members["deploy/job.sh"]) != receipt["job_sha256"]):
        raise ValueError("cluster protocol or training registry differs")
    for name, expected in manifest["files"].items():
        if name in members and (len(members[name]) != expected["bytes"]
                                or sha(members[name]) != expected["sha256"]):
            raise ValueError("sealed training source differs")
    # All archive and identity checks finish before this private root is made.
    root.mkdir(mode=0o700)
    for name, raw in sorted(members.items()):
        write_new(root.joinpath(*PurePosixPath(name).parts), raw)
    for specification in protocol["training_inputs"]:
        relative = PurePosixPath(specification["relative_path"])
        if relative.is_absolute() or ".." in relative.parts:
            raise ValueError("training input escapes the exclusive root")
        copy_registered_input(Path(specification["path"]),
                              root.joinpath(*relative.parts), specification)
    for relative, expected in manifest["files"].items():
        path = root.joinpath(*PurePosixPath(relative).parts)
        if path.is_symlink() or not path.is_file() or path.stat().st_size != expected["bytes"]:
            raise ValueError("deployed training file differs: " + relative)
        with path.open("rb") as stream:
            digest = hashlib.sha256()
            for block in iter(lambda: stream.read(1 << 20), b""):
                digest.update(block)
        if digest.hexdigest() != expected["sha256"]:
            raise ValueError("deployed training content differs: " + relative)
    (root / "slurm").mkdir(mode=0o700)
    binding = {"device": root.stat().st_dev, "inode": root.stat().st_ino,
               "uid": root.stat().st_uid, "mode": stat.S_IMODE(root.stat().st_mode)}
    if binding["mode"] != 0o700:
        raise ValueError("cluster root is not private")
    deployment = {"status": "DEPLOYED_NO_TRAINING", "root": REMOTE,
                  "root_binding": binding, "payload_sha256": receipt["payload_sha256"],
                  "protocol_sha256": receipt["protocol_sha256"],
                  "registry_sha256": receipt["registry_sha256"],
                  "manifest_sha256": receipt["manifest_sha256"],
                  "job_sha256": receipt["job_sha256"],
                  "registered_training_inputs": 10}
    record = canonical(deployment)
    write_new(root / "deploy/deployment.json", record)
    print(json.dumps({**deployment, "deployment_sha256": sha(record)},
                     sort_keys=True), flush=True)


if __name__ == "__main__":
    main()

ZJ_TARGET_DEPLOY
